(function () {
  'use strict';

  const COUNTRIES = [
    {
      id: 'mexico',
      lang: 'es-MX',
      flag: '🇲🇽',
      name: 'México',
      greeting: '¡Qué onda wey, bienvenido al equipo!'
    },
    {
      id: 'colombia',
      lang: 'es-CO',
      flag: '🇨🇴',
      name: 'Colombia',
      greeting: '¡Quiubo parce, todo bien con vos!'
    },
    {
      id: 'argentina',
      lang: 'es-AR',
      flag: '🇦🇷',
      name: 'Argentina',
      greeting: '¡Che boludo, re copado laburar acá!'
    },
    {
      id: 'chile',
      lang: 'es-CL',
      flag: '🇨🇱',
      name: 'Chile',
      greeting: '¡Cachai po, bienvenido a la wea!'
    },
    {
      id: 'peru',
      lang: 'es-PE',
      flag: '🇵🇪',
      name: 'Perú',
      greeting: '¡Causa, qué bacán estar con ustedes!'
    },
    {
      id: 'usa',
      lang: 'en-US',
      flag: '🇺🇸',
      name: 'USA',
      greeting: "Hey y'all, mighty glad you're here!"
    },
    {
      id: 'españa',
      lang: 'es-ES',
      flag: '🇪🇸',
      name: 'España',
      greeting: '¡Tío, qué guay molar en este equipo!'
    }
  ];

  const toggleBtn       = document.querySelector('#country-dropdown .dropdown__toggle');
  const toggleFlag      = document.querySelector('#country-dropdown .dropdown__toggle-flag');
  const toggleLabel     = document.querySelector('#country-dropdown .dropdown__toggle-label');
  const dropdownMenu    = document.querySelector('#country-dropdown .dropdown__menu');
  const greetingDisplay = document.querySelector('#greeting-display');
  const greetingFlag    = document.querySelector('#greeting-display .greeting__flag');
  const greetingPhrase  = document.querySelector('#greeting-display .greeting__phrase');
  const greetingCountry = document.querySelector('#greeting-display .greeting__country');

  function updateGreeting(country) {
    greetingFlag.textContent    = country.flag;
    greetingPhrase.textContent  = country.greeting;
    greetingCountry.textContent = country.name;
    document.documentElement.setAttribute('lang', country.lang);
    greetingDisplay.classList.add('is-active');
  }

  function closeDropdown() {
    dropdownMenu.classList.remove('is-active');
    toggleBtn.classList.remove('is-active');
  }

  function handleItemClick(event) {
    var item      = event.currentTarget;
    var countryId = item.dataset.countryId;
    var country   = COUNTRIES.find(function (c) { return c.id === countryId; });
    if (!country) { return; }
    toggleFlag.textContent  = country.flag;
    toggleLabel.textContent = country.name;
    updateGreeting(country);
    closeDropdown();
  }

  function handleToggleClick() {
    dropdownMenu.classList.toggle('is-active');
    toggleBtn.classList.toggle('is-active');
  }

  function handleDocumentClick(event) {
    var dropdown = document.querySelector('#country-dropdown');
    if (!dropdown.contains(event.target)) {
      closeDropdown();
    }
  }

  function init() {
    toggleBtn.addEventListener('click', handleToggleClick);

    var items = dropdownMenu.querySelectorAll('.dropdown__item');
    items.forEach(function (item) {
      item.addEventListener('click', handleItemClick);
    });

    document.addEventListener('click', handleDocumentClick);
  }

  init();

})();

/* === VARIABLES GLOBALES === */
:root {
  /* Colores */
  --color-primary: #1a1a2e;
  --color-secondary: #16213e;
  --color-accent: #0f3460;
  --color-highlight: #e94560;
  --color-text-primary: #ffffff;
  --color-text-secondary: #a8b2d8;
  --color-surface: #1e2a45;
  --color-surface-hover: #263554;
  --color-border: #2d3f6b;

  /* Tipografía */
  --font-family-base: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
    Oxygen, Ubuntu, sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.875rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 2rem;
  --font-size-xxl: 3rem;
  --font-weight-normal: 400;
  --font-weight-bold: 700;
  --line-height-base: 1.5;

  /* Espaciado */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-xxl: 3rem;

  /* Bordes y sombras */
  --border-radius-sm: 4px;
  --border-radius-md: 8px;
  --border-radius-lg: 16px;
  --border-width: 1px;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 20px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 8px 40px rgba(0, 0, 0, 0.7);

  /* Transiciones */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width-content: 800px;
  --dropdown-min-width: 220px;
  --dropdown-max-height: 320px;
}

/* === RESET & BASE === */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  background-color: var(--color-primary);
  color: var(--color-text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

ul,
ol {
  list-style: none;
  margin: 0;
  padding: 0;
}

a {
  text-decoration: none;
  color: inherit;
}

img {
  max-width: 100%;
  display: block;
}

/* === LAYOUT: #app === */
#app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  align-items: center;
}

/* === COMPONENTE: .header === */
.header {
  width: 100%;
  background-color: var(--color-secondary);
  border-bottom: var(--border-width) solid var(--color-border);
  padding: var(--spacing-lg) var(--spacing-md);
  text-align: center;
  box-shadow: var(--shadow-sm);
}

.header__title {
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-text-primary);
  margin: 0;
  letter-spacing: 0.02em;
}

@media (min-width: 768px) {
  .header__title {
    font-size: var(--font-size-xxl);
  }
}

/* === LAYOUT: main === */
main {
  flex: 1;
  width: 100%;
  max-width: var(--max-width-content);
  margin: 0 auto;
  padding: var(--spacing-xl) var(--spacing-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-xl);
}

/* === COMPONENTE: .dropdown === */
.dropdown {
  position: relative;
  width: 100%;
  max-width: var(--dropdown-min-width);
}

.dropdown__toggle {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  width: 100%;
  padding: var(--spacing-sm) var(--spacing-md);
  background-color: var(--color-surface);
  color: var(--color-text-primary);
  border: var(--border-width) solid var(--color-border);
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-base);
  font-family: var(--font-family-base);
  cursor: pointer;
  transition: background-color var(--transition-fast),
              border-color var(--transition-fast);
  user-select: none;
}

.dropdown__toggle:hover,
.dropdown__toggle:focus-visible {
  background-color: var(--color-surface-hover);
  border-color: var(--color-highlight);
  outline: none;
}

.dropdown__toggle.is-active {
  border-color: var(--color-highlight);
  background-color: var(--color-surface-hover);
}

.dropdown__toggle-flag {
  font-size: var(--font-size-lg);
  line-height: 1;
  flex-shrink: 0;
}

.dropdown__toggle-label {
  flex: 1;
  text-align: left;
  font-size: var(--font-size-base);
}

/* --- Menú desplegable --- */
.dropdown__menu {
  display: none;
  position: absolute;
  top: calc(100% + var(--spacing-xs));
  left: 0;
  width: 100%;
  min-width: var(--dropdown-min-width);
  max-height: var(--dropdown-max-height);
  overflow-y: auto;
  background-color: var(--color-surface);
  border: var(--border-width) solid var(--color-border);
  border-radius: var(--border-radius-md);
  box-shadow: var(--shadow-md);
  list-style: none;
  z-index: 100;
}

.dropdown__menu.is-active {
  display: block;
}

.dropdown__item {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  cursor: pointer;
  color: var(--color-text-primary);
  font-size: var(--font-size-base);
  transition: background-color var(--transition-fast);
}

.dropdown__item:hover,
.dropdown__item:focus-visible {
  background-color: var(--color-surface-hover);
  outline: none;
}

.dropdown__item-flag {
  font-size: var(--font-size-lg);
  line-height: 1;
  flex-shrink: 0;
}

.dropdown__item-name {
  font-size: var(--font-size-base);
  color: var(--color-text-primary);
}

/* === COMPONENTE: .greeting === */
.greeting {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-md);
  width: 100%;
  max-width: var(--max-width-content);
  background-color: var(--color-surface);
  border: var(--border-width) solid var(--color-border);
  border-radius: var(--border-radius-lg);
  padding: var(--spacing-xl) var(--spacing-lg);
  box-shadow: var(--shadow-lg);
  text-align: center;
}

.greeting.is-active {
  display: flex;
}

.greeting__flag {
  font-size: var(--font-size-xxl);
  line-height: 1;
}

.greeting__phrase {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  color: var(--color-text-primary);
  margin: 0;
  line-height: var(--line-height-base);
}

@media (min-width: 768px) {
  .greeting__phrase {
    font-size: var(--font-size-xl);
  }
}

.greeting__country {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  margin: 0;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

/* === COMPONENTE: .footer === */
.footer {
  width: 100%;
  background-color: var(--color-secondary);
  border-top: var(--border-width) solid var(--color-border);
  padding: var(--spacing-md);
  text-align: center;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}
